TITLE = "The Drop: Bien's Alusa Continua, Rema's E-Mortal Boy, Otile Brown and more"
TAG = "The Drop"
H1 = "The Drop: five new releases"
DEK = "Bien goes big on Alusa Continua, Rema finally gets Wizkid on a record, and Otile Brown, the GTA VI album and Toro y Moi fill out a heavy Friday."
META = "The Drop · 20 November 2026 · 5 min read"
LEAD = ("img/drop2-bien.jpg", "Bien's Alusa Continua artwork", "@qualitycontrolmusic / Instagram", "Artwork")

BODY = [
("p", "Kenya had a big Friday. Bien's long-awaited album and a new project from Otile Brown both landed on 20 November, the same day Rema put out his first EP in three years. Add a 34-track album built around the biggest game launch in years and a quiet piano record from Toro y Moi, and there's plenty to get through this weekend. Here's where to start."),
("list", "posters", [
 ("01", "img/drop2-bien.jpg", "Alusa Continua", "Bien", "Album · out Friday 20 November", [
   "Bien's new album runs to 17 tracks and pulls in guests from Kenya, the rest of the continent and the US: 2 Chainz, Alikiba, Joshua Baraka, Oxlade and Femi One are all on it. The title plays on his middle name, Alusa, and the old liberation slogan <em>A luta continua</em>, “the struggle continues”.",
   "The Kenyan roll call runs just as deep. Papa Gen Z joins 2 Chainz on “Signs”, Coster Ojwang is on “Kaumbete”, and Femi One and Papaa Maasai share “Mayolo”, with Ywaya Tajiri, Bryce One, Tulwap Kipsigis and Nono Melodies also in the credits. We first wrote about the album when he <a href=\"bien-alusa-continua.html\">announced it in October</a>."]),
 ("02", "img/drop2-rema.jpg", "E-Mortal Boy (EMB)", "Rema", "EP · out Friday 20 November", [
   "Rema's first EP since <em>Ravage</em> in 2023 is seven tracks long, and it opens with the record people have waited years for: “Feel Alright” is his first official song with Wizkid.",
   "The singles “TEA” and “Oh No” are on it too. French-Congolese singer Theodora joins him on “SUGA”, the American producer BNYX is on “Tanzania”, and London and Kah-Lo close things out on “Bang Bang”. It's out through Mavin Records and Jonzing World."]),
 ("03", "img/drop2-otile.jpg", "The Problem Child", "Otile Brown", "Out Friday 20 November", [
   "Otile Brown has been counting down to this one since late October, when he posted the artwork with the date on it. <em>The Problem Child</em> is out now, and “Hello” is a good first listen."]),
 ("04", "img/drop2-gta.jpg", "Grand Theft Auto VI: The Album", "Various artists", "Soundtrack · out this week", [
   "Rockstar Games and Atlantic Records put together 34 original songs for the game, and the album landed alongside it this week. Travis Scott, Playboi Carti, Dua Lipa, Morgan Wallen, PinkPantheress and Fred again.. are all on it.",
   "There's an African stake in it too: Burna Boy has a song on it, “Bigger”. Justice open the record with Michael McDonald on “Starting From Zero”, and Keith Richards, Lana Del Rey and JENNIE turn up further down. If you want the backstory on why the whole world was waiting for this game, read our <a href=\"gta-6-why-its-a-big-deal.html\">GTA 6 explainer</a>."]),
 ("05", "img/drop2-toro.jpg", "Unusua", "Toro y Moi", "Album · out Friday 20 November", [
   "Chaz Bear announced this one with almost no fuss, simply putting it up on his Bandcamp page. It's seven tracks, described as an instrumental, ambient record, and he performed, arranged and produced it himself in studios around Berkeley and Sausalito.",
   "“Proof”, the piano piece he put out in October, is on it, along with “Motive”. It's out on Company Studio. Put it on when the weekend needs to slow down."]),
]),
("p", "<small>Artwork: Bien via @qualitycontrolmusic, Rema via @heisrema, Otile Brown via @otilebrown, GTA VI: The Album via @rockstargames, Toro y Moi via @pitchfork, all on Instagram.</small>"),
]

